-- Rules generated by `hyprdeb apply` from ~/.config/hyprdeb/settings.toml.
-- Loaded with pcall, so a broken generated file cannot stop the rest of this config; a missing file is silent.
-- pcall also hides the failure from Hyprland (configerrors stays empty, no error bar), so show a notification.
do
  local path = (os.getenv("HOME") or "") .. "/.config/hypr/hyprdeb-settings.lua"
  local f = io.open(path, "r")
  if f then
    f:close()
    local ok, err = pcall(dofile, path)
    if not ok then
      pcall(hl.notification.create, {
        text = "hyprdeb: " .. path .. " failed to load; fix settings.toml and run: hyprdeb apply\n" .. tostring(err),
        timeout = 15000,
        color = "rgba(ff5555ff)",
      })
    end
  end
end

-- hypridle gets its listeners from this generated file (sourced by hypridle.conf). Without it hypridle has no rules and
-- nothing locks on idle, so say so (install.sh also recreates it with the defaults, and `hyprdeb apply` rewrites it).
do
  local idle = (os.getenv("HOME") or "") .. "/.config/hypr/hyprdeb-idle.conf"
  local f = io.open(idle, "r")
  if f then
    f:close()
  else
    pcall(hl.notification.create, {
      text = "idle lock disabled: ~/.config/hypr/hyprdeb-idle.conf missing, run hyprdeb apply",
      timeout = 15000,
      color = "rgba(ff5555ff)",
    })
  end
end
